<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {getDispatchBuildings,saveDispatchSettings,claimDispatchTask,actOnDispatchTask,type DispatchTask,type DispatchTaskAction} from '../api/dispatch';
import type {Building} from '../api/types';import {useDispatchBoard} from '../composables/useDispatchBoard';import {managerPresence} from '../composables/useManagerPresence';import {dateTime,errorText,notify} from '../ui';
import {currentDispatchTask} from '../composables/dispatchPlan';
import Icon from '../components/Icon.vue';import Drawer from '../components/Drawer.vue';import DispatchTaskCard from '../components/dispatch/DispatchTaskCard.vue';import DispatchAvailability from '../components/dispatch/DispatchAvailability.vue';import DispatchTravelEditor from '../components/dispatch/DispatchTravelEditor.vue';

const {board,busy,error,lastCheckedAt,changedOrders,routeChanges,refresh,replan}=useDispatchBoard();
const buildings=ref<Building[]>([]),settingsOpen=ref(false),travelOpen=ref(false),operationBusy=ref(false),operationError=ref(''),blockedTask=ref<DispatchTask>(),blockReason=ref('');
const mine=computed(()=>board.value?.routes.find(route=>route.manager.userId===board.value?.me.userId));
const ownTasks=computed(()=>[...(mine.value?.tasks||[])].sort((a,b)=>a.sequence-b.sequence));
const current=computed(()=>currentDispatchTask(ownTasks.value));
const next=computed(()=>ownTasks.value.find(task=>task.orderId!==current.value?.orderId&&task.state!=='BLOCKED'));
const remaining=computed(()=>ownTasks.value.filter(task=>task.orderId!==current.value?.orderId&&task.orderId!==next.value?.orderId));
const otherRoutes=computed(()=>board.value?.routes.filter(route=>route.manager.userId!==board.value?.me.userId)||[]);
const availabilityWarning=computed(()=>{const me=board.value?.me;if(!me)return '';if(!me.online)return '当前尚未确认前台活跃状态，恢复连接后会自动同步。';if(!me.acceptingNewTasks)return '你已暂停接受新任务，现有办理责任仍保留。';if(!me.availableUntil)return '尚未设置本次工作时段，因此暂不参与新增任务安排。';if(Date.parse(me.availableUntil)<=Date.now())return '上次可用时段已结束，请设置新的截止时刻后参与新增任务安排。';return '';});
const actionsDisabled=computed(()=>operationBusy.value||busy.value||!!error.value||!!board.value?.dirty);
const canDepart=(task:DispatchTask)=>task.orderId===next.value?.orderId&&!current.value;
async function taskAction(action:'claim'|DispatchTaskAction,task:DispatchTask){
  if(action==='block'){blockedTask.value=task;blockReason.value='';operationError.value='';return;}
  operationBusy.value=true;operationError.value='';
  try{if(action==='claim')await claimDispatchTask(task,board.value!.revision);else await actOnDispatchTask(task,action,action==='resume'?'受阻情况已解除，可重新安排':undefined);notify(action==='claim'?'推荐工单已接下，办理责任已确认':action==='depart'?'已记录出发，下一站已锁定':action==='arrive'?'已记录到达现场，请在工单中填写处理进度':'受阻情况已解除，路线将自动更新');await refresh();}catch(e){operationError.value=errorText(e);await refresh();}finally{operationBusy.value=false;}
}
async function block(){if(!blockedTask.value)return;operationBusy.value=true;operationError.value='';try{await actOnDispatchTask(blockedTask.value,'block',blockReason.value.trim());blockedTask.value=undefined;blockReason.value='';notify('已记录受阻原因，工单办理责任保持不变');await refresh();}catch(e){operationError.value=errorText(e);}finally{operationBusy.value=false;}}
async function toggleAccepting(){if(!board.value)return;operationBusy.value=true;operationError.value='';try{await saveDispatchSettings({acceptingNewTasks:!board.value.me.acceptingNewTasks,expectedVersion:board.value.me.version});notify(board.value.me.acceptingNewTasks?'已暂停接受新任务':'已恢复接受新任务');await refresh();}catch(e){operationError.value=errorText(e);}finally{operationBusy.value=false;}}
async function manualReplan(){operationBusy.value=true;operationError.value='';try{await replan();notify('已重新规划剩余任务');}catch(e){operationError.value=errorText(e);}finally{operationBusy.value=false;}}
function settingsSaved(){notify('本次接单与位置设置已保存');void refresh();}
onMounted(async()=>{try{buildings.value=await getDispatchBuildings();}catch(e){operationError.value=errorText(e);}});
</script>
<template><div class="page-heading"><div><p class="section-note">宿管现场服务</p><h1>任务调度</h1><p>新增工单与人员变化自动更新剩余路线，已经出发和正在处理的任务保持稳定。</p></div><div class="page-actions"><button class="btn" :disabled="busy" @click="refresh">刷新计划</button><button class="btn" @click="travelOpen=true">通行时间</button></div></div><div v-if="error" class="error-banner" role="alert">{{error}}<br>当前保留上次成功读取的计划，重新连通前不执行新的调度操作。<button @click="refresh">重新读取</button></div><p v-if="operationError&&!blockedTask" class="error-banner" role="alert">{{operationError}}</p><p v-if="!board&&busy" class="loading" role="status">正在读取人员与任务计划…</p><template v-if="board"><div class="dispatch-summary"><div><span>在线宿管</span><strong class="num">{{board.onlineCount}}<small>人</small></strong></div><div><span>参与调度</span><strong class="num">{{board.participatingCount}}<small>人</small></strong></div><div><span>已安排任务</span><strong class="num">{{board.metrics.assignedCount}}<small>笔</small></strong></div><div><span>暂未安排</span><strong class="num">{{board.metrics.unassignedCount}}<small>笔</small></strong></div></div><section class="dispatch-presence"><div><span class="dispatch-presence-label"><i :class="{connected:managerPresence.state==='online'}"/>{{board.me.acceptingNewTasks?'接受新任务':'暂停新任务'}}</span><p>同账号多端只计一人。{{managerPresence.state==='background'?'页面在后台，前台心跳已暂停。':managerPresence.state==='error'?'心跳暂未回应，请检查连接。':'前台每30秒同步活跃状态。'}}</p><small v-if="managerPresence.lastResponseAt">最近心跳回应 {{dateTime(managerPresence.lastResponseAt)}}</small></div><div><p>{{board.me.positionUpdatedAt?'当前位置':'默认出发点（未确认）'}}：{{board.me.positionBuildingName?board.me.positionBuildingName+' · '+board.me.positionFloorNo+'层':'尚未确认'}}</p><small>{{board.me.availableUntil?'可用到 '+dateTime(board.me.availableUntil):'未设置可用截止时刻'}}<template v-if="board.me.positionUpdatedAt"> · 位置确认 {{dateTime(board.me.positionUpdatedAt)}}</template></small></div><div class="button-row"><button class="btn primary" :disabled="operationBusy||!board.me.online" @click="toggleAccepting">{{board.me.acceptingNewTasks?'暂停接单':'接受新任务'}}</button><button class="btn" @click="settingsOpen=true">设置位置与时段</button></div></section><section v-if="availabilityWarning" class="dispatch-availability-warning" role="status"><div><strong>当前暂不参与新增任务安排</strong><p>{{availabilityWarning}}</p></div><button class="btn" @click="settingsOpen=true">设置工作时段</button></section><div class="dispatch-sync-line"><span>计划版本 <b class="num">{{board.revision}}</b> · {{dateTime(board.generatedAt)}}</span><span v-if="board.dirty" class="dispatch-updating" role="status">有新变化，正在更新剩余路线…</span><span v-else>前台每5秒检查新计划 · 最近读取 {{dateTime(lastCheckedAt)}}</span></div><section v-if="board.changes.length||routeChanges.length" class="dispatch-changes" aria-live="polite"><h2>本次计划变化</h2><ul><li v-for="(change,i) in board.changes" :key="i">{{change}}</li></ul><details v-if="routeChanges.length" class="dispatch-route-diff" open><summary>与上次读取相比，{{routeChanges.length}} 笔任务路线有变化</summary><ul><li v-for="change in routeChanges" :key="change.orderId"><RouterLink :to="'/repairs/'+change.orderId">{{change.title}}</RouterLink><span>{{change.detail}}</span></li></ul></details></section><div class="dispatch-layout"><div class="dispatch-route-column"><section class="dispatch-route-section"><header><div><h2>我的当前任务</h2><p>到达现场与维修完成分别记录。</p></div></header><DispatchTaskCard v-if="current" :task="current" own :highlighted="changedOrders.has(current.orderId)" :busy="actionsDisabled" @action="taskAction"/><div v-else class="dispatch-route-empty">目前没有在途或正在现场处理的任务。</div></section><section class="dispatch-route-section"><header><div><h2>下一站</h2><p>先接下推荐，再记录出发；已出发的下一站不会被自动调换。</p></div></header><DispatchTaskCard v-if="next" :task="next" own :can-depart="canDepart(next)" :highlighted="changedOrders.has(next.orderId)" :busy="actionsDisabled" @action="taskAction"/><div v-else class="dispatch-route-empty">当前没有下一站。新任务可行时会自动加入剩余路线。</div></section><section class="dispatch-route-section"><header><div><h2>其余任务</h2><p v-if="mine">预计剩余工作 {{mine.workloadMinutes}} 分钟 · 通行 {{mine.travelMinutes}} 分钟 · 等待 {{mine.waitingMinutes}} 分钟</p></div><span class="muted">{{remaining.length}} 笔</span></header><div class="dispatch-remaining"><DispatchTaskCard v-for="task in remaining" :key="task.orderId" :task="task" own :highlighted="changedOrders.has(task.orderId)" :busy="actionsDisabled" @action="taskAction"/></div><div v-if="!remaining.length" class="dispatch-route-empty">没有其他待访问任务。</div></section></div><aside class="dispatch-aside"><section class="panel"><header class="panel-head"><div><h2>未安排及原因</h2><p>没有可行路线的任务不会被静默忽略。</p></div></header><div class="dispatch-unassigned"><article v-for="entry in board.unassigned" :key="entry.task.orderId"><div class="dispatch-unassigned-heading"><strong>{{entry.task.buildingName}} {{entry.task.roomNo}}</strong><span>本单候选 {{entry.candidateCount}} 人</span></div><h3>{{entry.task.title}}</h3><p>{{entry.reason}}</p><div class="button-row"><RouterLink :to="'/repairs/'+entry.task.orderId" class="text-link">查看工单与安排 →</RouterLink><button v-if="entry.task.state==='BLOCKED'&&entry.task.handlerUserId===board.me.userId" class="text-link" :disabled="actionsDisabled" @click="taskAction('resume',entry.task)">恢复安排</button></div></article><p v-if="!board.unassigned.length" class="empty-state">当前所有可访问任务均已安排。</p></div></section><section class="dispatch-estimate-note"><h2>估算口径</h2><p>按楼栋、楼层与人工配置的通行时间估算；未确认的访问时段可协商，预计到达不代表已确认预约。</p><dl><div><dt>当前路线预计通行</dt><dd>{{board.metrics.travelMinutes}} 分钟</dd></div><div><dt>按提交顺序预计通行</dt><dd>{{board.metrics.baselineTravelMinutes<0?'暂无可行对照顺序':board.metrics.baselineTravelMinutes+' 分钟'}}</dd></div><div><dt>最长个人预计负载</dt><dd>{{board.metrics.maxWorkloadMinutes}} 分钟</dd></div></dl><button class="btn" :disabled="operationBusy||busy" @click="manualReplan">{{operationBusy?'正在办理…':'手动重新规划'}}</button><small>系统会自动响应新增、完工与人员变化；手动操作用于补充更新。</small></section></aside></div><section class="dispatch-other-routes"><h2>负责范围内的其他路线</h2><p class="form-note">只展示你有权查看的任务；查看在线人员不会扩大楼栋权限。</p><details v-for="route in otherRoutes" :key="route.manager.userId" class="dispatch-other-route"><summary><span>{{route.manager.displayName}}<small>{{route.manager.online?'在线':'暂不在线'}} · {{route.manager.acceptingNewTasks?'接受新任务':'暂停新任务'}}</small></span><span>{{route.tasks.length}} 笔 · 预计负载 {{route.workloadMinutes}} 分钟</span></summary><div class="dispatch-remaining"><DispatchTaskCard v-for="task in route.tasks" :key="task.orderId" :task="task" :highlighted="changedOrders.has(task.orderId)"/><p v-if="!route.tasks.length" class="empty-state">此宿管在可见范围内暂无已安排任务。</p></div></details><p v-if="!otherRoutes.length" class="dispatch-route-empty">当前没有其他可见宿管路线。</p></section></template><DispatchAvailability v-if="settingsOpen&&board" :manager="board.me" :buildings="buildings" @close="settingsOpen=false" @saved="settingsSaved"/><DispatchTravelEditor v-if="travelOpen" :buildings="buildings" @close="travelOpen=false;refresh()"/><Drawer v-if="blockedTask" title="记录暂时受阻" :subtitle="blockedTask.buildingName+' '+blockedTask.roomNo+' · '+blockedTask.title" :busy="operationBusy" :dirty="!!blockReason" @close="blockedTask=undefined"><form class="form" @submit.prevent="block"><p class="info-note">受阻后仍保留原办理责任。情况解除后再恢复安排，不会将当前处理中的工单自动派给他人。</p><label>受阻原因 *<textarea v-model.trim="blockReason" required minlength="2" maxlength="500" placeholder="例如：正在等待配件，或学生暂时不在宿舍"/></label><p v-if="operationError" class="error-banner" role="alert">{{operationError}}</p><button class="btn primary" :disabled="operationBusy">{{operationBusy?'正在保存…':'保存受阻原因'}}</button></form></Drawer></template>
